verify:
choices = {o: choices[n] for o, n in {'C': 'A', 'B': 'B', 'D': 'C', 'A': 'D'}.items()}; answer = {'A': 'C', 'B': 'B', 'C': 'D', 'D': 'A'}[answer]  # shuffled: original letters
def iv(s, v):
    u = s.strip()[2:-2].replace('\\le', '<=').replace('\\ge', '>=')
    if u.startswith(v + ' '):
        return value(u).as_set()
    L, Rt = u.split(' ' + v + ' ')
    return value(L + ' ' + v).as_set() & value(v + ' ' + Rt).as_set()
t = symbols('t')
S = solve_univariate_inequality(300 - 6*t > 40 + 7*t, t, relational=False) & solve_univariate_inequality(40 + 7*t >= 100, t, relational=False)
assert S == Interval.Ropen(Rational(60, 7), 20)
ok = [k for k in choices if iv(choices[k], 't') == S]
assert ok == [answer]
